window.SKIM_PAPERS["1705.03551"] = {"concepts": [{"id": "answer-string-distant-supervision", "name": "Distant supervision by answer-string match", "tier": "minor", "parent": null, "summary": "Question-answer pairs are written by trivia enthusiasts with no document in front of them, and evidence documents are retrieved afterwards; a document is kept as supervision for a question only if the answer string literally occurs in it. The training signal is therefore an assumption, not an annotation: if the answer string is present, the document is treated as answering the question.", "explanation": "The dataset is built by first collecting 95,956 question-answer pairs from 14 trivia and quiz-league websites (questions shorter than four tokens are dropped as too simple or too vague), and only then retrieving text that might support each answer. Because retrieval is automatic, no document is guaranteed to contain the facts a question actually asks for, so the whole collection rests on the distant-supervision assumption borrowed from relation extraction: presence of the answer string implies the document answers the question. Documents that do not contain the answer string are filtered out entirely, leaving 662,659 evidence documents over the 95K pairs, roughly six per question on average; the unfiltered release has 110,495 pairs and about 740K documents. The paper measures how often the assumption holds by having a human annotator try to answer questions using only the retrieved documents, abstaining unless the minimal facts are present: accuracy is 79.6% on the Wikipedia side and 75.3% on the web side, which the authors report as evidence the assumption is valid over 75% of the time. The counter-case they give is a document that mentions the answer entity for unrelated reasons - a page saying \"The Guns of Navarone is a 1961 British-American epic adventure war film directed by J. Lee Thompson\" contains the answer string but does not support a question about the Dodecanese Campaign. So a model trained on this data is trained on labels that are wrong roughly a fifth to a quarter of the time, and the error is systematically of one kind: spurious string matches rather than random noise. The authors note the data would equally support a multi-instance \"at least once\" formulation instead of treating every matching document as positive, but they do not use one. They also note the data could support a formulation where some documents lack the answer and a model must abstain, which they leave to future work.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2 (\"Data and Distant Supervision\"), Section 3 (\"Dataset Collection\"), Section 4 (\"Evidence analysis\"), Table 2", "ownerPaper": "1705.03551", "sources": {"paperId": "1705.03551", "note": "Section 2 (\"Data and Distant Supervision\"), Section 3 (\"Dataset Collection\"), Section 4 (\"Evidence analysis\"), Table 2", "sections": [], "pages": []}}, {"id": "wikipedia-domain-construction", "name": "The Wikipedia domain and its per-question document pooling", "tier": "minor", "parent": null, "summary": "The dataset splits into two domains with different evidence sources and different data-point definitions. In the Wikipedia domain, evidence pages come from entity-linking the question, all of a question's pages are pooled into one example, and no question is repeated.", "explanation": "Two evidence sources are collected. For the web domain, each question (never the answer, to avoid biasing results) is sent to the Bing Web search API, the top 50 URLs are taken, pages from the scraped trivia sites and any URL containing the keywords trivia, question, or answer are removed, and the top 10 remaining pages are crawled with PDFs and ill-formatted documents pruned. For the Wikipedia domain, an off-the-shelf entity linker (TAGME) is run over the question text to find Wikipedia entities mentioned in it, and those entities' pages become the evidence documents - so Wikipedia evidence is selected by what the question talks about, not by search relevance. The two domains are then organised differently because their redundancy differs. Web results are expected to be highly redundant, so each question-answer-document tuple is an independent data point with a single document, and the same question recurs many times across data points; this yields about 650K training examples. Wikipedia facts are generally stated only once, so all of a question's pages are pooled into one data point (1.8 documents per question on average) and each question appears exactly once; this yields about 78K examples. Wikipedia splits are 61,888 / 7,993 / 7,701 questions for train / dev / test, with 110,648 / 14,229 / 13,661 documents. Documents in either domain are long - 2,895 words on average, against the roughly 122-word single paragraphs of paragraph-level reading comprehension datasets. When a model must produce one answer from several pooled documents, the paper predicts independently per document and sums confidences: for a candidate A_i produced from documents D_i,1 ... D_i,n with confidences c_i,1 ... c_i,n, score(A_i) = sum_k c_i,k, and the highest-scoring candidate is selected.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 3 (\"Dataset Collection\"), Section 2 (\"Data and Distant Supervision\"), Section 5.3 (aggregation equation), Table 2, Table 6", "ownerPaper": "1705.03551", "sources": {"paperId": "1705.03551", "note": "Section 3 (\"Dataset Collection\"), Section 2 (\"Data and Distant Supervision\"), Section 5.3 (aggregation equation), Table 2, Table 6", "sections": [], "pages": []}}, {"id": "answer-span-approximation", "name": "Approximating answer spans by first string match", "tier": "minor", "parent": null, "summary": "Because questions were authored independently of the documents, the data contains answer strings but no marked answer spans. A span-prediction model is trained by taking the first occurrence of the answer string in the document as the gold span.", "explanation": "Span-extraction models need start and end positions inside a context, and this dataset does not have them: the answers are free-form strings written by trivia authors before any evidence existed. The paper's fix is a heuristic - find the first match of the answer string in the evidence document and treat that match's start and end offsets as the gold span. Nothing checks that the first occurrence is the occurrence the question is about, so the heuristic compounds the underlying distant-supervision noise: even in a document that genuinely answers the question, the first mention of the answer entity may be an unrelated one, for instance in a lead sentence, a list, or an infobox-like fragment. Answers are also of a kind that recurs: 92.85% of answers are Wikipedia titles (32% person, 23% location, 5% organization, 40% miscellaneous, with many titles being common phrases such as barber or soup), 4.17% are numerical expressions, and the remainder are open-ended noun and verb phrases. The paper reports an oracle score alongside its results - the upper bound on exact-match accuracy given that the correct answer must actually be found in the retained evidence - and that oracle sits at roughly 82-83% for the span model under distant supervision, below 100% precisely because of filtering and truncation. Anyone reusing this data as span supervision inherits both the string-match assumption and this first-occurrence approximation.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 5.3 (\"Neural model\"), Section 6.3 and footnote 9 (oracle score), Table 4, Table 7", "ownerPaper": "1705.03551", "sources": {"paperId": "1705.03551", "note": "Section 5.3 (\"Neural model\"), Section 6.3 and footnote 9 (oracle score), Table 4, Table 7", "sections": [], "pages": []}}, {"id": "first-400-token-training-filter", "name": "The first-400-tokens training filter and 800-word truncation", "tier": "minor", "parent": null, "summary": "Training documents are restricted to those where the answer string appears within the first 400 tokens, and documents are truncated to the first 800 words at prediction time. Both are stated as concessions to compute and model scale, not as claims about where answers belong.", "explanation": "Documents average 2,895 words, far beyond what a paragraph-level span model was designed to read, so the paper applies two separate length rules. For training, in both domains it keeps only those documents where the answer appears in the first 400 tokens, stated explicitly as a way to keep training time manageable; documents whose answer occurrence falls later are simply not trained on. For running the model, the evidence document is truncated to its first 800 words. The authors tried the obvious alternative of splitting long documents into smaller sub-documents and report that it degrades performance, because most sub-documents do not contain the answer and so present the model with unanswerable inputs. On the web side, training additionally uses a random sample of 80,000 documents rather than all of them, and the feature-based ranking baseline is trained on a random sample of 50,000 questions. The cost of the length rules shows up directly in the error analysis: of 100 incorrect predictions inspected, 15 were cases where the answer was not in the clipped document at all (against 19 where no provided document contained the evidence, 7 predictions from an incorrect document, 29 paraphrasing, 11 distractor entities, 18 requiring reasoning over multiple sentences). The paper calls designing scalable techniques that use the entirety of the data an open direction. So a \"first 400 tokens\" passage set derived from this dataset is not a curated set of answer-bearing paragraphs - it is the subset that survived a compute-motivated cut, and the surviving text is a document prefix that may contain the answer string for reasons unrelated to the question.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 6.2 (\"Experimental Setup\"), Section 5.3 and footnote 8 (truncation), Table 8 (error analysis)", "ownerPaper": "1705.03551", "sources": {"paperId": "1705.03551", "note": "Section 6.2 (\"Experimental Setup\"), Section 5.3 and footnote 8 (truncation), Table 8 (error analysis)", "sections": [], "pages": []}}, {"id": "em-f1-with-aliases", "name": "Evaluation: exact match and F1 with Wikipedia aliases, plus verified subsets", "tier": "minor", "parent": null, "summary": "Scoring uses the same exact-match and token-level F1 metrics as paragraph-level reading comprehension, but with Wikipedia aliases of the answer entity accepted as correct. A human-verified subset of dev and test separates dataset noise from model error.", "explanation": "The metrics are exact match (EM) and F1 over the words in the answer. Because most answers are entities, a single surface string is too strict, so for answers that are Wikipedia entities the Wikipedia aliases of that entity are accepted as valid alongside the given answer; for numerical and free-form answers the single given answer is the only ground truth. The evaluation unit differs by domain for the same redundancy reason that shapes the data: the Wikipedia domain is scored per question, since the needed facts are generally stated once, while the web domain is scored per document, since around six documents per question repeat the same information. Alongside the full distantly supervised dev and test sets, the paper releases verified subsets - the questions a human annotator could correctly answer from the provided documents alone - amounting to 297 dev and 584 test questions for Wikipedia and 322 dev and 733 test questions for web. Scores rise substantially on the verified subsets (for the strongest reported system, roughly 40 EM under distant supervision against roughly 45-51 EM verified), which is the paper's way of showing how much of the apparent difficulty is noisy supervision rather than genuine model failure. The human ceilings reported are 79.7% for Wikipedia and 75.4% for web, and the paper's own baselines - a random-entity heuristic at about 13 EM, a boosted-tree entity ranker at about 23-25 EM, and a span-prediction network at about 40-41 EM - all fall well short of them.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 6.1 (\"Evaluation Metrics\"), Section 6.2, Table 6, Table 7", "ownerPaper": "1705.03551", "sources": {"paperId": "1705.03551", "note": "Section 6.1 (\"Evaluation Metrics\"), Section 6.2, Table 6, Table 7", "sections": [], "pages": []}}], "items": [], "edges": [], "themes": [], "pages": [], "narrative": null, "insights": null, "reading": [], "refs": {"accessed": []}, "regions": [], "pdfPages": 0, "readerKind": "pdf", "sections": []};
